<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserGroupMembership\Domain\ValueObject;

use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFail;

class UserGroupMembershipUserVO
{
    public static function from(UserGroupMembershipUserVO|UserRef $value): UserGroupMembershipUserVO
    {
        return self::fromUnsafe($value);
    }
    public static function tryFrom(mixed $value, ConstraintFailList $list): ?UserGroupMembershipUserVO
    {
        if ($value instanceof UserGroupMembershipUserVO) {
            // If is a ValueObject, its already validated... nothing to append
            return $value;
        } elseif (is_a($value, UserRef::class)) {
            return new UserGroupMembershipUserVO($value);
        } else {
            $list->add(new ConstraintFail('wrong_type', ['user'], [$value], ['UserRef']));
            return null;
        }
    }
    private static function fromUnsafe(mixed $value): UserGroupMembershipUserVO
    {
        if ($value instanceof UserGroupMembershipUserVO) {
            // If is a ValueObject, its already validated
            return $value;
        } else {
            // If is not a ValueObject, validation is need and exception throw
            $errorsList = new ConstraintFailList();
            $candidate = self::tryFrom($value, $errorsList);
            if ($errorsList->hasErrors()) {
                throw $errorsList->asConstraintException();
            }
            \assert($candidate instanceof UserGroupMembershipUserVO);
            return $candidate;
        }
    }
    /**
     * private constructor to avoid build a value without all the rule validations.
     */
    private function __construct(
        private readonly UserRef $user
    ) {
    }
    public function value(): UserRef
    {
        return $this->user;
    }
    public function equals(?UserGroupMembershipUserVO $other): bool
    {
        return $this->value()->uid() == $other?->value()?->uid();
    }
}
